<content>
1: import { defineStore } from 'pinia'
2: import { hasDateField } from '../types/inspection'
3: export type InspectionType = 'pre' | 'mid' | 'post'
4: export type FormValues = Record<string, unknown>
5: export interface StoragePort { get(key: string): unknown; set(key: string, value: unknown): void }
6: const key = 'flood-demo-v1'
7: export interface FloodRecord { id: string; kind: InspectionType | 'rescue'; status: 'submitted' | 'draft'; values: FormValues; createdAt: string }
8: interface DraftEntry { values: FormValues; savedAt: string }
9: interface SavedData { version: 1; drafts: Partial<Record<InspectionType, DraftEntry>>; records?: FloodRecord[] }
10: export type HistoryKind = InspectionType | 'rescue'
11: export interface HistoryQuery { kinds: HistoryKind[]; status: 'all' | 'draft' | 'submitted'; keyword?: string }
12: export function createFloodStore(storage: StoragePort, mode: string = 'demo') {
13:   return defineStore('flood', () => {
14:     function read(): SavedData {
15:       if (mode !== 'demo') throw new Error('真实接口尚未接入，请提供接口协议后在store中接入；当前模式不能使用演示数据')
16:       const data = storage.get(key) as SavedData | undefined
17:       if (data == null || data === ('' as unknown)) return { version: 1, drafts: {} }
18:       if (data.version !== 1) throw new Error('本地数据版本不兼容，请导出备份后清理本地演示数据')
19:       if (!data.drafts || typeof data.drafts !== 'object' || Array.isArray(data.drafts) || (data.records != null && !Array.isArray(data.records))) throw new Error('本地数据损坏，请备份后清理本地演示数据')
20:       return JSON.parse(JSON.stringify(data)) as SavedData
21:     }
22:     function normalizeDraft(entry: DraftEntry | FormValues): DraftEntry {
23:       const candidate = entry as DraftEntry
24:       if (candidate && typeof candidate === 'object' && 'values' in candidate && candidate.values && typeof candidate.values === 'object') return { values: candidate.values, savedAt: String(candidate.savedAt ?? '') }
25:       return { values: entry as FormValues, savedAt: '' }
26:     }
27:     function saveDraft(kind: InspectionType, values: FormValues) {
28:       validatePhotos(values)
29:       const data = read()
30:       data.drafts[kind] = { values: JSON.parse(JSON.stringify(values)), savedAt: new Date().toISOString() }
31:       storage.set(key, data)
32:     }
33:     function loadDraft(kind: InspectionType) {
34:       const entry = read().drafts[kind]
35:       return entry ? normalizeDraft(entry).values : null
36:     }
37:     function draftSavedAt(kind: InspectionType) {
38:       const entry = read().drafts[kind]
39:       return entry ? normalizeDraft(entry).savedAt || null : null
40:     }
41:     function validatePhotos(values: FormValues) {
42:       const photos = values.photos
43:       if (photos == null) return
44:       if (!Array.isArray(photos) || photos.length > 6 || photos.some(photo => photo.status !== 'done' || !photo.url)) throw new Error('照片尚未保存成功，请重试或删除；最多6张')
45:     }
46:     let submitting = false
47:     async function submitInspection(kind: InspectionType, values: FormValues) {
48:       if (submitting) throw new Error('正在提交，请稍候')
49:       submitting = true
50:       try {
51:       await Promise.resolve()
52:       validatePhotos(values)
53:       if (hasDateField(kind) && !/^\d{4}-\d{2}-\d{2}$/.test(String(values.date ?? ''))) throw new Error('请选择填报日期')
54:       for (const value of Object.values(values)) {
55:         if (typeof value === 'number' && (!Number.isInteger(value) || value < 0)) throw new Error('数量必须为非负整数')
56:       }
57:       const data = read()
58:       const record: FloodRecord = { id: `FX-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, kind, status: 'submitted', values: JSON.parse(JSON.stringify(values)), createdAt: new Date().toISOString() }
59:       data.records = [record, ...(data.records ?? [])]
60:       delete data.drafts[kind]
61:       storage.set(key, data)
62:       return record
63:       } finally { submitting = false }
64:     }
65:     function getRecord(id: string) { return read().records?.find(record => record.id === id) ?? null }
66:     function matchQuery(query: HistoryQuery) {
67:       const data = read()
68:       const drafts: FloodRecord[] = Object.entries(data.drafts).map(([kind, entry]) => {
69:         const draft = normalizeDraft(entry)
70:         return { id: `draft-${kind}`, kind: kind as InspectionType, status: 'draft' as const, values: draft.values, createdAt: draft.savedAt }
71:       })
72:       return [...drafts, ...(data.records ?? [])].filter(item => query.kinds.includes(item.kind) && (query.status === 'all' || item.status === query.status) && (!query.keyword || JSON.stringify(item.values).includes(query.keyword)))
73:     }
74:     async function fetchHistoryPage(query: HistoryQuery & { pageNum: number; pageSize: number }) {
75:       const all = matchQuery(query)
76:       const start = (query.pageNum - 1) * query.pageSize
77:       return { items: all.slice(start, start + query.pageSize), total: all.length, hasMore: start + query.pageSize < all.length }
78:     }
79:     async function countHistory(query: HistoryQuery) { return matchQuery(query).length }
80:     async function submitRescue(values: FormValues) {
81:       if (submitting) throw new Error('正在提交，请稍候')
82:       submitting = true
83:       try {
84:       await Promise.resolve()
85:       if (!String(values.contact ?? '').trim()) throw new Error('请填写联系人')
86:       if (!/^1\d{10}$/.test(String(values.phone ?? ''))) throw new Error('请填写有效的11位联系电话')
87:       if (!['一般', '紧急', '特级'].includes(String(values.level))) throw new Error('请选择紧急程度')
88:       if (!String(values.danger ?? '').trim() || !String(values.support ?? '').trim()) throw new Error('请填写险情与支援描述')
89:       if (!Array.isArray(values.photos) || values.photos.length === 0) throw new Error('请上传现场照片')
90:       validatePhotos(values)
91:       const data = read()
92:       const record: FloodRecord = { id: `QY-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, kind: 'rescue', status: 'submitted', values: JSON.parse(JSON.stringify(values)), createdAt: new Date().toISOString() }
93:       data.records = [record, ...(data.records ?? [])]
94:       storage.set(key, data)
95:       return record
96:       } finally { submitting = false }
97:     }
98:     return { saveDraft, loadDraft, draftSavedAt, submitInspection, submitRescue, getRecord, fetchHistoryPage, countHistory }
99:   })
100: }
101: export const useFloodStore = createFloodStore({
102:   get: key => uni.getStorageSync(key),
103:   set: (key, value) => uni.setStorageSync(key, value),
104: }, import.meta.env.VITE_DATA_MODE ?? 'demo')

