[{"type":"text","text":"# 苏住房G (zhi2-web-admin) 本地 nginx 部署 —— root 指向本项目 dist（vite outDir = 仓库根 dist）
# 代理对齐 env/.env.test 的 VITE_APP_PROXY_ADDRESS（苏住房 G 测试环境网关）
# 说明：/v2.0/evaluation/ 走本地 zhi2-evaluation（含 stdEvaluation 新模块），其余走测试环境网关
server {
    listen 8101;
    server_name localhost;
    root D:/repository/苏住房G/worktrees/dist;
    index index.html;
    charset utf-8;
    client_max_body_size 100m;

    proxy_http_version 1.1;
    proxy_set_header Connection "";
    proxy_set_header Host unlimited.g.h5.admin.web.v2.suzhufang.shiqu.suzhou.test.zhi.com;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_connect_timeout 60s;
    proxy_send_timeout 120s;
    proxy_read_timeout 120s;

    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|xlsx|json)$ {
        expires 7d;
        add_header Cache-Control "public" always;
        access_log off;
        try_files $uri =404;
    }
    location = /index.html {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
        add_header Pragma "no-cache";
    }

    # 本地后端：zhi2-evaluation:9608，经 9609 代理注入网关同款鉴权头（token_type/token/user_id/user_name）

    location ^~ /v2.0/evaluation/ {
        proxy_pass http://127.0.0.1:9609;
        proxy_set_header Host 127.0.0.1:9608;
    }

    # VITE_APP_BASE_API = 'v2.0' → 前端请求 /v2.0/...，网关实际路由前缀是 /api/v2.0/
    # 故此处必须做路径改写：/v2.0/x -> /api/v2.0/x
    location ^~ /v2.0/ {
