tool_input.content:
import type { InspectionType } from '../stores/flood'
export const titles: Record<InspectionType | 'rescue', string> = { pre: '汛前检查', mid: '汛中巡检', post: '汛后检查', rescue: '求援工单' }
export interface FieldSpec { key: string; label: string; type: 'count' | 'choice'; options?: string[] }
export interface CardSpec { key: string; title?: string; date?: boolean; fields: FieldSpec[]; note?: boolean }
const count = (key: string, label: string): FieldSpec => ({ key, label, type: 'count' })
const choice = (key: string, label: string, options: string[]): FieldSpec => ({ key, label, type: 'choice', options })

const preCards: CardSpec[] = [
  { key: 'basic', date: true, fields: [count('people', '出动巡查人员（人次）')] },
  {
    key: 'hazard',
    fields: [
      count('attachments', '加固外墙附着物/空调外机（单位：处）'),
      count('balconies', '提醒业主清理阳台搁置物（单位：处）'),
      count('trees', '加固或修剪倒伏风险树木（单位：株）'),
      count('barriers', '防淹防倒灌设施专项检查（单位：处）'),
      count('electrical', '涉电设备防雨防漏电检修（单位：处）'),
      count('hazards', '排查发现隐患数量（单位：条）'),
      count('resolved', '已落实整改隐患数量（单位：条）'),
      count('falling', '高空坠物风险源排查（单位：处）'),
      choice('drains', '雨水井清掏', ['是', '否']),
      choice('rooms', '配电房、电梯机房防水封堵', ['是', '否']),
      choice('pipes', '低洼楼栋疏通雨水管网', ['是', '否']),
    ],
  },
]

const midCards: CardSpec[] = [
  { key: 'road', title: '道路路基', fields: [choice('road', '小区地面／道路积水深度', ['轻度积水', '中度积水', '重度积水']), count('roadHazards', '隐患数量（单位：处）')] },
  { key: 'drain', title: '排水管网及环境', fields: [choice('drain', '雨水篦、集水井是否淤堵', ['正常', '异常'])] },
  { key: 'tree', title: '绿化树木', fields: [choice('tree', '小区绿化大树倾倒情况', ['正常', '异常']), count('treePoints', '问题点位数量')] },
  { key: 'charging', title: '非机动车充电设施', fields: [choice('charging', '充电桩、插座、线缆是否进水漏电短路', ['正常', '异常'])] },
  { key: 'power', title: '用电电气设施', fields: [choice('power', '用电电气设施运行情况', ['正常', '异常']), count('powerPoints', '问题点位数量')] },
  { key: 'wall', title: '楼栋外墙及附属设施', fields: [choice('wall', '楼栋外墙及附属设施情况', ['正常', '异常'])] },
  { key: 'underground', title: '地下空间', fields: [choice('underground', '地下空间积水与防倒灌情况', ['正常', '异常']), count('undergroundPoints', '问题点位数量')] },
]

const postCards: CardSpec[] = [
  { key: 'road', title: '道路路基', note: true, fields: [choice('road', '路基下沉、塌陷、空鼓、开裂', ['正常', '异常']), count('roadHazards', '隐患数量（单位：处）')] },
  { key: 'drain', title: '排水管网及环境', note: true, fields: [choice('drain', '雨水篦、集水井淤堵', ['正常', '异常'])] },
  { key: 'tree', title: '绿化树木', note: true, fields: [choice('tree', '根基松动、倾斜、断裂、枯枝', ['正常', '异常']), count('treePoints', '问题点位数量')] },
  { key: 'charging', title: '非机动车充电设施', note: true, fields: [choice('charging', '充电设施损坏情况', ['正常', '异常'])] },
  { key: 'power', title: '用电电气设施', note: true, fields: [choice('power', '用电设施恢复情况', ['正常', '异常']), count('powerPoints', '问题点位数量')] },
  { key: 'wall', title: '楼栋外墙及附属设施', note: true, fields: [choice('wall', '外墙及附属设施损坏情况', ['正常', '异常'])] },
  { key: 'underground', title: '地下空间', note: true, fields: [choice('underground', '地下空间排水恢复情况', ['正常', '异常']), count('undergroundPoints', '问题点位数量')] },
  { key: 'ledger', title: '台账处置', note: true, fields: [choice('ledger', '汛期隐患台账处置情况', ['正常', '异常'])] },
]

export function cardsFor(kind: InspectionType): CardSpec[] { return kind === 'pre' ? preCards : kind === 'mid' ? midCards : postCards }
export function fieldsFor(kind: InspectionType): FieldSpec[] { return cardsFor(kind).flatMap(card => card.fields) }
export function hasDateField(kind: InspectionType) { return cardsFor(kind).some(card => card.date) }
export function today() { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}` }
export function initialValues(kind: InspectionType): Record<string, unknown> {
  const values: Record<string, unknown> = { notes: {}, photos: [] }
  if (hasDateField(kind)) values.date = today()
  for (const card of cardsFor(kind)) {
    for (const field of card.fields) values[field.key] = field.type === 'count' ? 0 : (field.options?.[0] ?? '')
    if (card.note) (values.notes as Record<string, unknown>)[card.key] = ''
  }
  return values
}
export function isInspectionType(value: unknown): value is InspectionType { return value === 'pre' || value === 'mid' || value === 'post' }
export const demoUser = '张建国'

/* 归档截图（C:\Users\Administrator\Downloads\归档）中历史记录的工单标题文案。
   pre 的 title 对应「娄门路130号院落」类项目点，mid 对应汛中日常巡查，post 对应汛后恢复检查。 */
export const ticketTitles: Record<InspectionType, string> = {
  pre: '2026年度汛前全面安全排查',
  mid: '2026年度汛中日常防汛巡查记录',
  post: '2026年度汛后响应总结评估',
}
export const ticketPlaces: Record<InspectionType, string> = {
  pre: '娄门路130号院落',
  mid: '苏锦一村',
  post: '永林新村',
}
/* 求援工单状态文案：与归档截图中「救援处置中」「已响应」一致 */
export const rescueStatusText = '救援处置中'
export const levelTone: Record<string, 'normal' | 'urgent' | 'critical'> = { 一般: 'normal', 紧急: 'urgent', 特级: 'critical' }

