/* ===== 设计令牌（取自 C:\Users\Administrator\Downloads\归档 截图取色） ===== */
:root{
  --c-bg:#f7f9fd;
  --c-surface:#ffffff;
  --c-fill:#f2f4f8;
  --c-fill-strong:#e6e8ec;
  --c-line:#e6e8ec;
  --c-text:#191c1f;
  --c-text-2:#424655;
  --c-text-3:#737686;
  --c-brand:#075ed1;
  --c-brand-soft:#edf1ff;
  --c-warn:#ef7f13;
  --c-warn-soft:#fff0dc;
  --c-critical:#c31d24;
  --c-critical-soft:#ffe9e8;
  --c-orange:#fe9c2d;
  --r-card:12px;
  --r-ctl:8px;
  --shadow-card:0 1px 2px #0000000d;
}

page{
  min-height:100vh;
  background:var(--c-bg);
  color:var(--c-text);
  font-family:'Noto Sans SC:Medium','Noto Sans SC',-apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',sans-serif;
  font-size:16px;
  font-weight:400;
  line-height:1.5;
  box-sizing:border-box;
}
view,text,image,input,textarea,scroll-view,label{box-sizing:border-box;margin:0;padding:0;border:0 solid}
image{display:block;max-width:100%}
input,textarea{font:inherit;color:inherit;background:transparent;outline:none;border:0 solid}

/* 屏幕容器：固定页头 64px 与底栏 */
.screen{min-height:100vh;min-height:100dvh;background:var(--c-bg);padding:calc(64px + var(--status-bar-height,0px)) 0 calc(76px + env(safe-area-inset-bottom));position:relative;margin:auto;max-width:720px;box-sizing:border-box}
.form-screen{padding-bottom:calc(92px + env(safe-area-inset-bottom))}

/* 固定页头 */
.app-header{position:fixed;z-index:20;top:var(--status-bar-height,0px);left:0;right:0;margin:0 auto;max-width:720px;height:64px;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.88);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);box-shadow:0 1px 8px #0000000a}
.app-header-title{font-size:18px;font-weight:500;line-height:27px}
.app-back{position:absolute;left:16px;top:0;height:64px;display:flex;align-items:center}
.app-back-glyph{font-family:sans-serif;font-weight:400;font-size:36px;line-height:1}

/* ===== 工作台 ===== */
.workspace{display:flex;gap:12px;padding:10px 16px}
.workspace-aside{width:80px;display:flex;flex-direction:column;gap:8px;flex:none}
.side-tab{height:76px;text-align:center;border-radius:12px;background:var(--c-fill);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;font-size:12px;position:relative}
.side-tab-image{width:20px;height:20px}
.side-tab.active{background:var(--c-brand-soft);color:#004fd0}
.side-tab.active::before{content:'';position:absolute;left:0;top:8px;bottom:8px;width:4px;border-radius:0 9px 9px 0;background:#004fd0}
.apps{flex:1;min-width:0}
.section-title{height:38px;padding:0 12px;background:var(--c-surface);border-radius:var(--r-ctl);display:flex;align-items:center;justify-content:space-between;box-shadow:var(--shadow-card);font-size:14px;margin-bottom:8px}
.section-title-text{font-weight:700}
.section-title-count{font-size:11px;color:var(--c-text-2);background:var(--c-fill-strong);padding:2px 8px;border-radius:99px}
.app-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.app-card{height:116px;text-align:center;background:var(--c-surface);border-radius:var(--r-card);box-shadow:var(--shadow-card);display:flex;flex-direction:column;align-items:center;justify-content:center}
.icon-well{width:48px;text-align:center;height:48px;border-radius:16px;display:grid;place-items:center;margin-bottom:6px;background:#eff6ffcc}
.icon-well-image{width:24px;height:24px}
.tone-1{background:#eef2ffcc}
.tone-2{background:#f0fdfacc}
.tone-3{background:#fffbeacc}
.app-card-title{font-size:14px;line-height:20px;font-weight:700}
.app-card-sub{font-size:10px;color:var(--c-text-2);line-height:14px}

/* 底部导航 */
.bottom-nav{position:fixed;z-index:20;bottom:0;left:0;right:0;margin:0 auto;max-width:720px;height:calc(64px + env(safe-area-inset-bottom));padding-bottom:env(safe-area-inset-bottom);background:rgba(247,249,253,.92);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);display:flex;justify-content:space-around;box-shadow:0 -2px 12px #0000000a}
.bottom-nav-item{width:33%;text-align:center;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:11px}
.bottom-nav-image{width:20px;height:20px;margin-bottom:2px}
.bottom-nav-item.selected{color:#004fd0}

/* ===== 表单 ===== */
.form-content{display:flex;flex-direction:column;gap:12px;padding:12px 16px}
.form-card{background:var(--c-surface);border-radius:var(--r-card);padding:16px;box-shadow:var(--shadow-card);display:flex;flex-direction:column;gap:16px}
.field{display:flex;flex-direction:column;gap:5px}
.field-label,.upload-label{font-size:14px;line-height:20px;display:block}
.field-required{color:#ba1a1a}
.field-input,.field-textarea{background:var(--c-fill);border-radius:var(--r-ctl);padding:12px;font-size:14px;width:100%;display:block}
.field-input{height:45px;line-height:21px}
.date-input{display:flex;align-items:center;justify-content:space-between}
.date-icon{width:20px;height:20px;flex:none}
.field-textarea{height:92px;min-height:92px;line-height:21px;resize:vertical}
.field-counter{font-size:11px;color:var(--c-text-2);line-height:16px;text-align:center;display:block}
.stepper{height:48px;border-radius:var(--r-ctl);background:var(--c-fill);padding:6px 8px;display:flex;align-items:center;gap:8px}
.stepper-button{width:44px;height:36px;border-radius:var(--r-ctl);background:var(--c-fill-strong);font-size:20px;line-height:1;display:flex;align-items:center;justify-content:center;color:var(--c-text)}
.stepper-button.disabled{opacity:.45}
.stepper-value{flex:1;text-align:center;color:var(--c-text-3);font-size:16px}
.choices{display:flex;gap:8px}
.choice{flex:1;text-align:center;background:var(--c-fill);border-radius:7px;height:36px;color:var(--c-text-2);font-size:16px;display:flex;align-items:center;justify-content:center}
.choice.chosen{background:var(--c-brand);color:#fff}
/* 紧急程度：三档，默认橙色选中，特级为深红 */
.choices.levels .choice{height:48px}
.choices.levels .choice.chosen{background:var(--c-orange);color:#fff}
.choices.levels .choice.chosen.critical{background:var(--c-critical)}
.inspection-section-title{font-size:16px;font-weight:700;line-height:24px;border-left:3px solid #0868e8;padding-left:8px}

/* 照片 */
.photo-row{display:flex;gap:8px;height:104px}
.photo-thumb{min-width:0;flex:1;border-radius:var(--r-ctl);overflow:hidden;position:relative}
.photo-thumb-image{width:100%;height:100%;object-fit:cover;border-radius:var(--r-ctl)}
.photo-upload{min-width:0;flex:1;border-radius:var(--r-ctl);background:var(--c-fill);color:var(--c-brand);font-size:28px;display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:hidden}
.photo-upload-text{font-size:10px;color:var(--c-text-2);margin-top:5px}
.photo-remove{position:absolute;right:4px;top:4px;width:20px;height:20px;border-radius:50%;background:rgba(0,0,0,.55);color:#fff;font-size:13px;line-height:20px;text-align:center}
.photo-state{position:absolute;left:0;right:0;bottom:0;padding:2px;font-size:10px;color:#fff;background:rgba(0,0,0,.6);text-align:center}
.photo-state.failed{background:#b42318}
.photo-caption{position:absolute;left:0;right:0;bottom:0;padding:2px;font-size:10px;color:#fff;background:rgba(0,0,0,.5);text-align:center}
.photo-hint{font-size:11px;color:var(--c-text-2);line-height:16px;margin-top:2px}

/* 底部操作栏 */
.action-bar{position:fixed;z-index:20;bottom:0;left:0;right:0;margin:0 auto;max-width:720px;height:calc(72px + env(safe-area-inset-bottom));padding:12px 16px;padding-bottom:calc(12px + env(safe-area-inset-bottom));background:#fffffff0;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);display:flex;gap:8px;box-shadow:0 -4px 16px #0000000f}
.action-button{flex:1;text-align:center;border-radius:6px;background:var(--c-brand);color:#fff;font-size:16px;display:flex;align-items:center;justify-content:center}
.action-button.secondary{flex:0 0 90px;background:var(--c-surface);color:var(--c-text);border:1px solid #d7dae0}
.action-bar.orange .action-button{background:var(--c-orange);border-radius:12px;font-size:18px;font-weight:700}
.action-button.disabled{opacity:.6}
/* 详情页底部：单个主按钮占满 */
.action-bar.single .action-button{flex:1}
.rescue-fab{position:fixed;text-align:center;z-index:12;right:20px;right:max(20px,calc(50% - 340px));bottom:84px;background:var(--c-orange);color:#fff;border-radius:99px;padding:12px 18px;font-size:16px;box-shadow:0 6px 18px #fe9c2d55}
.form-alert{position:fixed;z-index:19;left:0;right:0;margin:0 auto;max-width:720px;bottom:88px;padding:10px 16px;background:#fff0ee;color:#b42318;font-size:13px;line-height:20px;border-radius:var(--r-ctl);box-shadow:0 4px 16px #0000001a}
.form-alert.success{background:#eaf6f0;color:#16754c}

/* ===== 历史记录 ===== */
.history-top{padding:8px 16px 0}
.history-body{padding:0 16px 8px}
.tabs{display:flex;background:#eef0f4;border-radius:var(--r-card);padding:4px;margin-bottom:10px}
.tab{flex:1;text-align:center;height:34px;border-radius:var(--r-ctl);font-size:13px;display:flex;align-items:center;justify-content:center}
.tab.chosen{background:var(--c-surface);color:var(--c-brand)}
.filters{display:flex;gap:8px;overflow:auto;margin-bottom:16px}
.filter{white-space:nowrap;text-align:center;background:var(--c-fill-strong);padding:5px 12px;border-radius:99px;font-size:12px;line-height:18px;flex:none}
.filter.chosen{background:var(--c-brand);color:#fff}
.filter.urgent.chosen{background:var(--c-warn-soft);color:var(--c-warn)}
/* 工单卡片：编号 + 状态 → 标题 → 时间/巡检人 → 底部按钮（右对齐） */
.ticket{background:var(--c-surface);border-radius:var(--r-card);padding:16px;margin-bottom:12px;box-shadow:var(--shadow-card);position:relative;display:flex;flex-direction:column}
.ticket.urgent{border-left:4px solid var(--c-critical)}
.ticket.critical{border-left:4px solid var(--c-critical)}
.ticket-head{display:flex;align-items:flex-start;justify-content:space-between;gap:8px}
.ticket-number{color:var(--c-text-3);font-size:10px;line-height:20px;flex:1;overflow-wrap:anywhere}
.ticket-status{background:var(--c-warn-soft);color:var(--c-warn);border-radius:99px;padding:2px 8px;font-size:11px;line-height:16px;flex:none;display:flex;align-items:center;gap:3px}
.ticket-status.done{background:var(--c-brand-soft);color:var(--c-brand)}
.ticket-status.critical{background:var(--c-critical-soft);color:var(--c-critical)}
.ticket-title{font-size:17px;line-height:25px;font-weight:700;margin:5px 0 8px;display:block;overflow-wrap:anywhere}
.ticket-meta{font-size:13px;color:#555b6e;line-height:20px;display:block}
.ticket-meta-icon{font-size:11px;color:var(--c-text-3)}
.ticket-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:12px}
.ticket-action{text-align:center;padding:7px 16px;border-radius:var(--r-ctl);background:#e9ecf1;font-size:12px;line-height:18px;color:var(--c-text)}
.ticket-action.primary{background:var(--c-brand);color:#fff}
.ticket-action.danger{background:var(--c-critical);color:#fff}
.ticket-empty{padding:40px 0;text-align:center;color:var(--c-text-3);font-size:13px}

/* ===== 详情页 ===== */
.detail-hero{background:var(--c-surface);border-radius:var(--r-card);padding:16px;box-shadow:var(--shadow-card);display:flex;flex-direction:column;gap:8px}
.detail-row{display:flex;align-items:flex-start;gap:8px;font-size:14px;line-height:22px}
.detail-row-label{flex:0 0 104px;color:var(--c-text-3)}
.detail-row-value{flex:1;min-width:0;color:var(--c-text);overflow-wrap:anywhere}
.detail-section{background:var(--c-surface);border-radius:var(--r-card);padding:16px;box-shadow:var(--shadow-card);display:flex;flex-direction:column;gap:12px}
.detail-choice{display:inline-flex;align-items:center;height:28px;padding:0 10px;border-radius:99px;background:var(--c-fill);color:var(--c-text-2);font-size:12px}
.detail-choice.chosen{background:var(--c-brand-soft);color:var(--c-brand)}
.detail-choice.warn{background:var(--c-warn-soft);color:var(--c-warn)}
.detail-note{background:var(--c-fill);border-radius:var(--r-ctl);padding:10px 12px;font-size:13px;line-height:20px;color:var(--c-text-2)}
.timeline{display:flex;flex-direction:column;gap:10px}
.timeline-item{display:flex;gap:10px;font-size:13px;line-height:20px}
.timeline-dot{width:8px;height:8px;border-radius:50%;background:var(--c-brand);flex:none;margin-top:6px}
.timeline-dot.done{background:var(--c-warn)}
.timeline-body{flex:1;min-width:0;color:var(--c-text-2)}

@media(min-width:620px){
  .workspace{padding:24px}
  .workspace-aside{width:100px}
  .app-grid{grid-template-columns:repeat(3,1fr)}
  .app-card{height:135px}
  .form-content{padding:20px 32px}
  .history-top{padding:20px 32px 0}
  .history-body{padding:0 32px 20px}
}

# 苏住房防汛C端（uni-app H5）本地 nginx 部署
# 构建产物：D:/repository/苏住房防汛C端/dist/build/h5
# 由 nginx.conf 的 include conf.d/*.conf 自动加载，无需改动主配置。
server {
    listen 8103;
    server_name localhost 127.0.0.1;
    root "D:/repository/苏住房防汛C端/dist/build/h5";
    index index.html;
    charset utf-8;

    # 静态资源长缓存，index.html 强制不走缓存，避免发版后 chunk 404
    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map)$ {
        expires 7d;
        add_header Cache-Control "public" always;
        access_log off;
        try_files $uri =404;
    }

    location = /index.html {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
    }

    # uni-app H5 使用 hash 路由，回退到 index.html 即可
    location / {
        try_files $uri $uri/ /index.html;
    }
}

