/**
 * 归档截图相似度比对（UI E2E 视觉回归）
 *
 * 基准：C:\Users\Administrator\Downloads\归档\*.png（8 张设计稿截图，812×1782 / 844×2009 / 844×2342）
 * 实现：本地 nginx 部署的 H5 产物（默认 http://127.0.0.1:8103/）
 *
 * 比对方式：两图按同尺寸设备像素比归一化后逐像素比对（delta>24 计为差异像素），
 * 输出差异比例与红色差异蒙层到 artifacts/archive-diff/。
 * 归档截图为 2x 设计稿，故以 deviceScaleFactor=2 + 视口 406×891 渲染（=812×1782 设备像素）。
 */
import { chromium } from '@playwright/test'
import { mkdirSync, writeFileSync, existsSync } from 'node:fs'
import { pathToFileURL } from 'node:url'
import { resolve } from 'node:path'

const BASE = process.env.E2E_BASE_URL || 'http://127.0.0.1:8103/'
const ARCHIVE = process.env.ARCHIVE_DIR || 'C:/Users/Administrator/Downloads/归档'
const OUT = 'artifacts/archive-diff'
mkdirSync(OUT, { recursive: true })

/* 每张归档截图对应的路由与交互步骤；seed 用于让列表/详情有可展示的数据 */
const scenes = [
  {
    name: '工作台',
    archive: '工作台.png',
    // 归档目录里没有单独的工作台截图，用「历史记录 · 防台防汛工单列表」的入口态代替，故此项仅截图不入报告
    optional: true,
    hash: '#/',
    steps: async () => {},
  },
  {
    name: '历史记录 · 防台防汛工单列表',
    archive: '历史记录 · 防台防汛工单列表.png',
    hash: '#/pages/history/index',
    seed: 'pre',
    steps: async page => {
      await page.getByRole('button', { name: '汛前检查', exact: true }).click()
      await page.getByRole('button', { name: '全部工单', exact: false }).click()
    },
  },
  {
    name: '历史记录 · 汛中巡检工单列表',
    archive: '历史记录 · 汛中巡检工单列表.png',
    hash: '#/pages/history/index',
    seed: 'mid',
    steps: async page => {
      await page.getByRole('button', { name: '汛中巡检', exact: true }).click()
      await page.getByRole('button', { name: '全部工单', exact: false }).click()
    },
  },
  {
    name: '汛前检查',
    archive: '汛前检查.png',
    hash: '#/pages/inspection/index?kind=pre',
    steps: async () => {},
  },
  {
    name: '汛中检查',
    archive: '汛中检查.png',
    hash: '#/pages/inspection/index?kind=mid',
    steps: async () => {},
  },
  {
    name: '汛后检查',
    archive: '汛后检查.png',
    hash: '#/pages/inspection/index?kind=post',
    steps: async () => {},
  },
  {
    name: '求援工单',
    archive: '求援工单.png',
    hash: '#/pages/rescue/index',
    steps: async page => {
      await page.locator('input').nth(0).fill('张建国（物业主管）')
      await page.locator('input').nth(1).fill('138 1234 5678')
      await page.locator('textarea').nth(0).fill('地下一层配电房入口处积水已漫过30厘米防汛挡水板，自备2台抽水泵电缆短路停转，存在变压器淹泡危险，急需大功率排涝支援。')
      await page.locator('textarea').nth(1).fill('紧急申请街道协调机动抢险专业队伍支援，调派大流量柴油抽水泵1台，补充沙袋50条协助加固防倒灌防线。')
    },
  },
  {
    name: '求援工单详情',
    archive: '求援工单详情.png',
    hash: '#/pages/detail/index',
    seed: 'rescue',
    steps: async page => {
      await page.getByRole('button', { name: '查看详情', exact: true }).first().click()
      await page.waitForSelector('.detail-hero', { timeout: 15000 })
    },
  },
  {
    name: '汛中巡检工单详情',
    archive: '汛中巡检工单详情.png',
    hash: '#/pages/detail/index',
    seed: 'mid',
    steps: async page => {
      await page.getByRole('button', { name: '查看详情', exact: true }).first().click()
      await page.waitForSelector('.detail-hero', { timeout: 15000 })
    },
  },
]

/* 演示数据：写入 localStorage 的 flood-demo-v1，让列表/详情有与归档截图同量级的内容 */
function seedData(kind) {
  const iso = new Date('2026-07-15T14:30:00+08:00').toISOString()
  const iso2 = new Date('2026-07-12T15:10:00+08:00').toISOString()
  const preValues = {
    date: '2026-07-15', people: 2, attachments: 3, balconies: 5, trees: 2, barriers: 4,
    electrical: 2, hazards: 1, resolved: 0, falling: 3, drains: '是', rooms: '是', pipes: '否', notes: {}, photos: [],
  }
  const midValues = {
    road: '轻度积水', roadHazards: 2, drain: '正常', tree: '正常', treePoints: 0,
    charging: '正常', power: '正常', powerPoints: 0, wall: '正常', underground: '异常', undergroundPoints: 1,
    photos: [],
  }
  const rescueValues = {
    contact: '张建国（物业主管）', phone: '13812345678', level: '紧急',
    danger: '地下一层配电房入口处积水已漫过30厘米防汛挡水板，自备2台抽水泵电缆短路停转，存在变压器淹泡危险，急需大功率排涝支援。',
    support: '紧急申请街道协调机动抢险专业队伍支援，调派大流量柴油抽水泵1台，补充沙袋50条协助加固防倒灌防线。',
    photos: [],
  }
  const records = []
  if (kind === 'pre') {
    records.push({ id: 'FX-20260715-0012', kind: 'pre', status: 'submitted', values: preValues, createdAt: iso })
    records.push({ id: 'FX-20260712-0005', kind: 'pre', status: 'submitted', values: preValues, createdAt: iso2 })
  } else if (kind === 'mid') {
    records.push({ id: 'FX-20260718-0008', kind: 'mid', status: 'submitted', values: midValues, createdAt: iso })
    records.push({ id: 'FX-20260718-0007', kind: 'mid', status: 'submitted', values: midValues, createdAt: iso2 })
  } else if (kind === 'rescue') {
    records.push({ id: 'QY-20260718-0003', kind: 'rescue', status: 'submitted', values: rescueValues, createdAt: iso })
  }
  return { version: 1, drafts: {}, records }
}

const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })

/* 归档截图尺寸决定设备像素比与 CSS 视口 */
async function metricsFor(archivePath) {
  const raw = await import('node:fs').then(m => m.readFileSync(archivePath))
  // PNG 尺寸在 IHDR：bytes 16..24
  if (raw[0] === 0x89 && raw[1] === 0x50) {
    return { width: raw.readUInt32BE(16), height: raw.readUInt32BE(20) }
  }
  // webp: 交给浏览器测量
  return null
}

const comparePage = await (await browser.newContext()).newPage()
await comparePage.goto('about:blank')

async function compare(name, archiveUrl, shot) {
  return comparePage.evaluate(async payload => {
    const load = src => new Promise((ok, bad) => { const img = new Image(); img.onload = () => ok(img); img.onerror = bad; img.src = src })
    const ref = await load(payload.ref)
    const mine = await load(payload.mine)
    const width = Math.min(ref.width, mine.width)
    const height = Math.min(ref.height, mine.height)
    const read = (img, w, h) => {
      const canvas = document.createElement('canvas'); canvas.width = w; canvas.height = h
      const ctx = canvas.getContext('2d'); ctx.drawImage(img, 0, 0, w, h)
      return ctx.getImageData(0, 0, w, h).data
    }
    const a = read(ref, width, height)
    const b = read(mine, width, height)
    const canvas = document.createElement('canvas'); canvas.width = width; canvas.height = height
    const ctx = canvas.getContext('2d')
    const diff = ctx.createImageData(width, height)
    let changed = 0
    let minX = width, minY = height, maxX = -1, maxY = -1
    for (let i = 0; i < a.length; i += 4) {
      const delta = Math.abs(a[i] - b[i]) + Math.abs(a[i + 1] - b[i + 1]) + Math.abs(a[i + 2] - b[i + 2])
      const pixel = i / 4
      const x = pixel % width, y = Math.floor(pixel / width)
      if (delta > 24) {
        changed++
        if (x < minX) minX = x; if (x > maxX) maxX = x
        if (y < minY) minY = y; if (y > maxY) maxY = y
        diff.data[i] = 255; diff.data[i + 1] = 0; diff.data[i + 2] = 0; diff.data[i + 3] = 255
      } else {
        diff.data[i] = a[i]; diff.data[i + 1] = a[i + 1]; diff.data[i + 2] = a[i + 2]; diff.data[i + 3] = 110
      }
    }
    ctx.putImageData(diff, 0, 0)
    return {
      refSize: { w: ref.width, h: ref.height },
      mineSize: { w: mine.width, h: mine.height },
      width, height, total: width * height, changed,
      ratio: +(changed / (width * height) * 100).toFixed(3),
      similarity: +(100 - changed / (width * height) * 100).toFixed(3),
      box: maxX < 0 ? null : { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 },
      png: canvas.toDataURL('image/png'),
    }
  }, { ref: archiveUrl, mine: shot })
}

const results = []
for (const scene of scenes) {
  const archivePath = resolve(ARCHIVE, scene.archive)
  if (!existsSync(archivePath)) { console.log(`跳过 ${scene.name}：归档截图不存在 ${archivePath}`); continue }

  const size = await metricsFor(archivePath)
  // 归档截图为 2x，用 2 倍 deviceScaleFactor 还原 CSS 视口
  const cssWidth = Math.round(size.width / 2)
  const cssHeight = Math.round(size.height / 2)
  const context = await browser.newContext({
    viewport: { width: cssWidth, height: cssHeight },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
    userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1',
  })
  const page = await context.newPage()

  // 先播种数据（需要同源 localStorage，故先打开目标站点）
  if (scene.seed) {
    await page.goto(BASE, { waitUntil: 'domcontentloaded' })
    const payload = JSON.stringify(seedData(scene.seed))
    await page.evaluate(data => { localStorage.setItem('flood-demo-v1', data) }, payload)
  }

  await page.goto(BASE + scene.hash, { waitUntil: 'domcontentloaded' })
  await page.waitForSelector('.app-header, .detail-hero, .ticket', { timeout: 20000 })
  await page.evaluate(async () => {
    try { await document.fonts.load('500 16px "Noto Sans SC:Medium"'); await document.fonts.ready } catch {}
  })
  await scene.steps(page)
  await page.waitForTimeout(1200)

  const shotBuf = await page.screenshot({ timeout: 60000 })
  const shotPath = `${OUT}/${scene.name.replace(/[\\/:*?"<>| ]/g, '_')}-mine.png`
  writeFileSync(shotPath, shotBuf)

  if (scene.optional) { console.log(`（跳过比对）${scene.name}：归档目录无对应截图`); await context.close(); continue }

  const archiveUrl = pathToFileURL(archivePath).href
  const shot = `data:image/png;base64,${shotBuf.toString('base64')}`
  const r = await compare(scene.name, archiveUrl, shot)
  writeFileSync(`${OUT}/${scene.name.replace(/[\\/:*?"<>| ]/g, '_')}-diff.png`, Buffer.from(r.png.split(',')[1], 'base64'))
  results.push({ scene: scene.name, ...r, png: undefined })
  console.log(`${scene.name}: 相似度 ${r.similarity}%（差异像素 ${r.changed}/${r.total}，参考 ${r.refSize.w}x${r.refSize.h}，实现 ${r.mineSize.w}x${r.mineSize.h}）`)
  await context.close()
}

await browser.close()

const avg = results.length ? +(results.reduce((s, r) => s + r.similarity, 0) / results.length).toFixed(2) : 0
writeFileSync(`${OUT}/report.json`, JSON.stringify({ generatedAt: new Date().toISOString(), base: BASE, average: avg, results }, null, 2))
console.log(`\n平均相似度：${avg}%（${results.filter(r => r.similarity >= 95).length}/${results.length} 页达到 95%）`)

