tool_input.content:
import type { InspectionType } from '../stores/flood'
export const titles: Record<InspectionType | 'rescue', string> = { pre: '汛前检查', mid: '汛中巡检', post: '汛后检查', rescue: '求援工单' }
export interface FieldSpec { key: string; label: string; type: 'count' | 'choice'; options?: string[]; required?: boolean; section?: boolean }
export interface CardSpec { key: string; title?: string; subtitle?: string; date?: boolean; fields: FieldSpec[]; note?: boolean; photos?: boolean }
const count = (key: string, label: string): FieldSpec => ({ key, label, type: 'count', required: true })
const choice = (key: string, label: string, options: string[]): FieldSpec => ({ key, label, type: 'choice', options, required: true })
const seg = (key: string, label: string, options: string[]): FieldSpec => ({ ...choice(key, label, options), section: true })

/* ===== 汛前检查：字段按归档截图（C:/Users/Administrator/Downloads/归档/汛前检查.png）逐条对齐 ===== */
const preCards: CardSpec[] = [
  {
    key: 'basic',
    date: true,
    fields: [count('people', '出动巡查人员（人次）')],
  },
  {
    key: 'hazard',
    fields: [
      count('attachments', '加固外墙附着物/空调外机（单位：处）'),
      count('balconies', '提醒业主清理阳台搁置物（单位：处）'),
      count('trees', '加固或修剪倒伏风险树木（单位：株）'),
