})

/* 归档截图中的「查看草稿」入口需要按列表主键 draft-<kind> 反查到草稿详情 */
test('草稿可按历史列表主键反查，非草稿主键返回空', () => {
  const store = createFloodStore(storage)()
  store.saveDraft('mid', { road: '轻度积水', notes: {} })
  const draft = store.getDraftByKey('draft-mid')
  expect(draft?.kind).toBe('mid')
  expect(draft?.status).toBe('draft')
  expect(draft?.values).toMatchObject({ road: '轻度积水' })
  expect(store.getDraftByKey('FX-20260715-0012')).toBeNull()
  expect(store.getDraftByKey('draft-pre')).toBeNull()
})

/* 归档截图的历史记录卡片同时显示草稿与已提交，切换类型/状态筛选后计数独立 */
test('历史记录草稿与已提交数量可分别统计', async () => {
  const store = createFloodStore(storage)()
  await store.submitInspection('post', { roadSubsidence: '无' })
  store.saveDraft('post', { roadSubsidence: '有' })
  expect(await store.countHistory({ kinds: ['post'], status: 'all' })).toBe(2)
  expect(await store.countHistory({ kinds: ['post'], status: 'draft' })).toBe(1)
  expect(await store.countHistory({ kinds: ['post'], status: 'submitted' })).toBe(1)
})

