.field-input > input{width:100%;height:38px;line-height:38px;display:block;background:transparent;border:0;font-size:13px;color:var(--c-text);padding:0}
.field-input > input::placeholder{color:var(--c-text-3)}
.field-textarea-wrap{position:relative;background:var(--c-fill);border-radius:6px;padding:8px 8px 20px}
.field-textarea-wrap .field-textarea.inner{background:transparent;padding:0;height:76px;min-height:76px;border-radius:0;line-height:20px;font-size:13px}
.field-count{position:absolute;right:8px;bottom:3px;font-size:11px;line-height:15px;color:var(--c-text-3)}
.date-icon{width:16px;height:16px;flex:none}
.field-textarea{height:92px;min-height:92px;line-height:21px;resize:vertical}
.field-counter{font-size:11px;color:var(--c-text-2);line-height:16px;text-align:center;display:block}
/* 步进器：归档截图中高度 48px 的一半 24px，两侧按钮 44×36 → 22×18 */
.stepper{height:40px;border-radius:6px;background:var(--c-fill);padding:4px 6px;display:flex;align-items:center;gap:6px}
.stepper-button{width:36px;height:30px;border-radius:6px;background:var(--c-fill-strong);font-size:17px;line-height:1;display:flex;align-items:center;justify-content:center;color:var(--c-text)}
.stepper-button.disabled{opacity:.45}
.stepper-value{flex:1;text-align:center;color:var(--c-text-3);font-size:14px}
.choices{display:flex;gap:8px}
.choice{flex:1;text-align:center;background:var(--c-fill);border-radius:6px;height:32px;color:var(--c-text-2);font-size:14px;display:flex;align-items:center;justify-content:center}
.choice.chosen{background:var(--c-brand);color:#fff}
/* 紧急程度：三档，默认橙色选中，特级为深红 */
.choices.levels .choice{height:40px;font-size:14px}
.choices.levels .choice.chosen{background:var(--c-orange);color:#fff}
.choices.levels .choice.chosen.critical{background:var(--c-critical)}
.inspection-section-title{font-size:15px;font-weight:700;line-height:22px;border-left:3px solid #0868e8;padding-left:8px}

